import sys
from math import sqrt

def count_divisors_sum_to(n):
    def sum_of_divisors(x):
        total = 0
        for i in range(1, int(sqrt(x)) + 1):
            if x % i == 0:
                total += i
                if i != x // i:
                    total += x // i
        return total

    count = 0
    for i in range(1, n + 1):
        if sum_of_divisors(i) == n:
            count += 1
    return count

A = int(sys.stdin.read().strip())
print(count_divisors_sum_to(A))
